public class UndoRedoService : IUndoRedoService
{
    private const int MaxActions = 10;

    private readonly Stack<IUndoRedoAction> _undoStack = new();
    private readonly Stack<IUndoRedoAction> _redoStack = new();

    /// <summary>Есть ли действия для отмены (Undo).</summary>
    public bool CanUndo => _undoStack.Count > 0;

    /// <summary>Есть ли действия для повтора (Redo).</summary>
    public bool CanRedo => _redoStack.Count > 0;

    /// <summary>
    /// Сохранить уже выполненное действие в историю.
    /// Caller сам вызывает repo-метод ДО Push.
    /// </summary>
    /// <param name="action">Действие с реализацией Undo/Redo.</param>
    public void Push(IUndoRedoAction action)
    {
        _undoStack.Push(action);
        _redoStack.Clear();

        if (_undoStack.Count > MaxActions)
        {
            var items = _undoStack.ToArray(); // [новый, ..., старый]
            _undoStack.Clear();
            for (int i = MaxActions - 1; i >= 0; i--)
                _undoStack.Push(items[i]);
        }
    }

    /// <summary>
    /// Отменить последнее действие (Undo).
    /// </summary>
    public void Undo()
    {
        if (!CanUndo)
            return;
        var action = _undoStack.Pop();

public RegistrationResult Register(string login, string password)
{
    var normalizedLogin = (login ?? string.Empty).Trim();

    if (normalizedLogin.Length == 0)
        return RegistrationResult.Fail("RegisterErrorLoginRequired");

    if (normalizedLogin.Length < 3)
        return RegistrationResult.Fail("RegisterErrorLoginShort");

    if (normalizedLogin.Length > 32)
        return RegistrationResult.Fail("RegisterErrorLoginLong");

    if (string.IsNullOrEmpty(password) || password.Length < 8)
        return RegistrationResult.Fail("RegisterErrorPasswordShort");

    if (_repo.GetUserByLogin(normalizedLogin) != null)
        return RegistrationResult.Fail("RegisterErrorLoginTaken");

    var user = new User
    {
        Id = Guid.NewGuid(),
        Login = normalizedLogin,
        PasswordHash = _passwordHasher.HashPassword(password),
        Role = UserRole.User,
    };

    _repo.AddUser(user);
    OpenSession(user);

    return RegistrationResult.Ok(user);
}
